const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const t=(key,params={})=>I18n.t(key,params);
const state={page:'overview',searches:[],listings:[],locations:[],selected:new Set(),listingSort:{field:null,direction:null},deleteName:null,marketKey:null,marketRange:'30D',retailLines:new Set(['dns','ozon','wildberries']),project:null,updateResult:null,updateChecking:false,desktopIntegration:null,integrationResult:null,integrationInstalling:false,settings:{default_interval_seconds:900,default_jitter_seconds:30,default_block_retry_delay_seconds:60,default_block_cooldown_seconds:900,default_max_block_retries:1,default_export_format:'json',default_search_editor:'simple',interface_language:'en',appearance_mode:'system',color_theme:'graphite',ui_refresh_seconds:2,market_lookback_days:30,linux_integration_prompt_dismissed:0}};
const titles={overview:['page.overview.eyebrow','nav.overview'],searches:['page.searches.eyebrow','page.searches.title'],listings:['page.listings.eyebrow','nav.listings'],market:['page.market.eyebrow','nav.market'],history:['page.history.eyebrow','nav.history'],sources:['page.sources.eyebrow','nav.sources'],settings:['page.settings.eyebrow','nav.settings']};
const h=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtDate=v=>v?new Intl.DateTimeFormat(I18n.language==='ru'?'ru-RU':'en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):t('time.never');
const ago=v=>{if(!v)return t('time.never');const s=Math.max(0,(Date.now()-new Date(v))/1000);if(s<60)return t('time.seconds',{n:Math.floor(s)});if(s<3600)return t('time.minutes',{n:Math.floor(s/60)});if(s<86400)return t('time.hours',{n:Math.floor(s/3600)});return fmtDate(v)};
const money=v=>v==null?'—':new Intl.NumberFormat('ru-RU').format(v)+' ₽';
const api=async(path,opts={})=>{const res=await fetch(path,{headers:{'Content-Type':'application/json'},...opts});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||`Request failed: ${res.status}`);return data};
const openExternal=async url=>{if(window.pywebview?.api?.open_external_url){await window.pywebview.api.open_external_url(url);return}window.open(url,'_blank','noopener')};
const toast=(msg,error=false)=>{const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;$('#toasts').append(el);setTimeout(()=>el.remove(),3600)};
const statusLabel=v=>t(`status.${String(v||'unknown').toLowerCase()}`)||t('common.unknown');
const recommendationLabel=v=>t(`recommendation.${v||'NOT ACTIONABLE'}`)||String(v||'');
const healthTag=v=>`<span class="tag ${h(v)}">${h(statusLabel(v))}</span>`;
const scoreBadge=l=>!l.is_actionable?`<span class="score-badge insufficient"><b>${l.score??'—'}</b><span>${h(recommendationLabel(l.recommendation))}</span></span>`:l.score==null?`<span class="score-badge insufficient"><b>—</b><span>${h(t('status.insufficient'))}</span></span>`:`<span class="score-badge ${h(l.recommendation.toLowerCase().replaceAll(' ','-'))}"><b>${l.score}</b><span>${h(recommendationLabel(l.recommendation))}</span></span>`;
const conditionBadge=l=>`<span class="condition-badge ${h((l.condition_class||'OK').toLowerCase())}">${h(statusLabel(l.condition_class||'OK'))}</span>`;
const availabilityBadge=l=>`<span class="availability-badge ${h(l.availability||'unknown')}">${h(statusLabel(l.availability))}</span>`;
const freshnessText=l=>l.availability==='active'?t('availability.seen',{time:ago(l.last_seen)}):l.availability==='stale'?t('availability.last_seen',{time:ago(l.last_seen)}):l.availability==='disappeared'?t('availability.gone',{time:ago(l.last_seen)}):l.availability==='archived'?t('availability.archived',{time:ago(l.last_seen)}):t('availability.unconfirmed');
const imagePlaceholder=()=>`<span class="listing-image-placeholder" role="img" aria-label="${h(t('listings.image'))}"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 17l4.5-5 3.5 4 2.5-3 5.5 6M8.5 8.5h.01"/></svg></span>`;
const listingImage=(url,variant='thumbnail')=>`<div class="listing-image ${h(variant)}">${url?`<img src="${h(url)}" alt="${h(t('listings.image'))}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:''}${imagePlaceholder()}</div>`;
function bindImageFallbacks(root=document){root.querySelectorAll('.listing-image img:not([data-image-bound])').forEach(image=>{image.dataset.imageBound='true';image.addEventListener('error',()=>{image.remove()},{once:true})})}
const systemTheme=window.matchMedia('(prefers-color-scheme: dark)');
function applyAppearance(settings=state.settings){const mode=['system','light','dark'].includes(settings.appearance_mode)?settings.appearance_mode:'system',theme=['graphite','moss','ember','plum'].includes(settings.color_theme)?settings.color_theme:'graphite',resolved=mode==='system'?(systemTheme.matches?'dark':'light'):mode;document.documentElement.dataset.mode=resolved;document.documentElement.dataset.modePreference=mode;document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=resolved;$$('[data-appearance-mode]').forEach(x=>{x.classList.toggle('active',x.dataset.appearanceMode===mode);x.setAttribute('aria-pressed',String(x.dataset.appearanceMode===mode))});$$('[data-color-theme]').forEach(x=>{x.classList.toggle('active',x.dataset.colorTheme===theme);x.setAttribute('aria-pressed',String(x.dataset.colorTheme===theme))})}
systemTheme.addEventListener?.('change',()=>{if((state.settings.appearance_mode||'system')==='system')applyAppearance()});

function refreshPageTitle(){const page=state.page;$('#page-eyebrow').textContent=t(titles[page][0]);$('#page-title').textContent=t(titles[page][1])}
function go(page){state.page=page;$$('.page').forEach(x=>x.classList.toggle('active',x.id===`page-${page}`));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));refreshPageTitle();loadPage(page)}
async function loadPage(page){try{if(page==='overview')await loadOverview();if(page==='searches')await loadSearches();if(page==='listings')await loadListings();if(page==='market')await loadMarket();if(page==='history')await loadHistory();if(page==='sources')await loadSources();if(page==='settings')await loadSettings()}catch(e){toast(e.message,true)}}

async function loadOverview(){const d=await api('/api/dashboard');const metrics=[[t('overview.new_listings'),d.new,t('overview.awaiting_review'),'＋'],[t('overview.interesting'),d.interesting,t('overview.marked_candidates'),'◆'],[t('overview.price_drops'),d.price_drops,t('overview.recorded_changes'),'↓'],[t('overview.active_searches'),d.active_searches,t('overview.independent_schedules'),'⌁']];$('#overview-metrics').innerHTML=metrics.map(x=>`<article class="metric-card"><div class="metric-top"><span>${h(x[0])}</span><span class="metric-icon">${x[3]}</span></div><div class="metric-value">${x[1]}</div><div class="metric-sub">${h(x[2])}</div></article>`).join('');renderSourceCards('#overview-sources',d.source_health);$('#timing-card').innerHTML=`<div class="timing-row"><small>${h(t('overview.last_scan'))}</small><strong>${h(fmtDate(d.last_scan_at))}</strong></div><div class="timing-row"><small>${h(t('overview.next_scan'))}</small><strong>${h(fmtDate(d.next_scan))}</strong></div><div class="timing-row"><small>${h(t('overview.current_state'))}</small><strong>${h(statusLabel(d.runtime.state))}</strong></div>`;renderActivity('#recent-activity',d.recent_activity,true)}
function renderSourceCards(target,sources){$(target).innerHTML=sources.map(s=>`<div class="source-card"><div class="source-card-top"><h3>${h(s.source)}</h3>${healthTag(s.health)}</div><dl><div><dt>${h(t('overview.last_success'))}</dt><dd>${h(ago(s.last_success_at))}</dd></div><div><dt>${h(t('overview.http_status'))}</dt><dd>${h(s.last_http_status??'—')}</dd></div><div><dt>${h(t('overview.transport'))}</dt><dd>${h(s.transport??'—')}</dd></div><div><dt>${h(t('overview.blocked_until'))}</dt><dd>${h(s.blocked_until?fmtDate(s.blocked_until):'—')}</dd></div></dl></div>`).join('')}

async function loadSearches(){state.searches=await api('/api/searches');$('#filter-search').innerHTML=`<option value="">${h(t('listings.all_searches'))}</option>`+state.searches.map(s=>`<option value="${h(s.name)}">${h(s.name)}</option>`).join('');$('#search-list').innerHTML=state.searches.length?state.searches.map(s=>`<article class="search-card"><div class="search-head"><div><span class="source-label">${h(s.source)}</span><h3>${h(s.name)}</h3>${healthTag(s.health)}</div><input class="toggle search-toggle" data-name="${h(s.name)}" type="checkbox" role="switch" aria-label="${h(`${t('search.enabled_field')}: ${s.name}`)}" aria-checked="${s.enabled?'true':'false'}" ${s.enabled?'checked':''}></div><div class="search-url" title="${h(s.url)}">${h(s.url)}</div><div class="search-stats"><div class="search-stat"><small>${h(t('search.interval').toUpperCase())}</small><strong>${Math.round(s.interval_seconds/60)}m ±${s.jitter_seconds}s</strong></div><div class="search-stat"><small>${h(I18n.language==='ru'?'РЕЗУЛЬТАТЫ':'RESULTS')}</small><strong>${s.last_result_count}</strong></div><div class="search-stat"><small>${h(I18n.language==='ru'?'ПОСЛЕДНИЙ СТАТУС':'LAST STATUS')}</small><strong>${h(s.last_status??'—')}</strong></div><div class="search-stat"><small>${h(I18n.language==='ru'?'СЛЕДУЮЩИЙ ЗАПУСК':'NEXT SCAN')}</small><strong>${h(s.next_scan?ago(s.next_scan):'—')}</strong></div></div><div class="search-actions"><button class="btn secondary run-search" data-name="${h(s.name)}">${h(t('search.run'))}</button><button class="btn ghost edit-search" data-name="${h(s.name)}">${h(t('search.edit'))}</button><button class="btn ghost delete-search" data-name="${h(s.name)}">${h(t('search.delete'))}</button></div></article>`).join(''):`<div class="empty" style="display:block">${h(t('search.empty'))}</div>`;bindSearchActions()}
function bindSearchActions(){$$('.search-toggle').forEach(x=>x.onchange=async()=>{x.setAttribute('aria-checked',String(x.checked));try{await api(`/api/searches/${encodeURIComponent(x.dataset.name)}/toggle`,{method:'POST',body:JSON.stringify({enabled:x.checked})});toast(x.checked?'Search enabled':'Search disabled');loadSearches()}catch(e){x.checked=!x.checked;x.setAttribute('aria-checked',String(x.checked));toast(e.message,true)}});$$('.run-search').forEach(x=>x.onclick=async()=>{const r=await api(`/api/searches/${encodeURIComponent(x.dataset.name)}/run`,{method:'POST'});toast(r.started?'Scan started':'A scan is already running')});$$('.edit-search').forEach(x=>x.onclick=()=>openSearch(state.searches.find(s=>s.name===x.dataset.name)));$$('.delete-search').forEach(x=>x.onclick=()=>{state.deleteName=x.dataset.name;$('#confirm-dialog').showModal()})}
function setEditor(mode){const f=$('#search-form');f.classList.toggle('simple-editor',mode==='simple');f.dataset.editor=mode;$$('.editor-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.editor===mode));$('#search-modal-title').textContent=t($('#search-original-name').value?'search.edit_title':'search.new_title');updateSourceControls()}
function updateSourceControls(){const source=$('#search-form').elements.source.value;$$('[data-source-control]').forEach(x=>x.hidden=x.dataset.sourceControl!==source)}
function openSearch(search=null){const f=$('#search-form');f.reset();$('#search-original-name').value=search?.name||'';$('#search-modal-title').textContent=search?'Edit search':'New search';const defaults={enabled:true,source:'avito',location_mode:'default',interval_seconds:state.settings.default_interval_seconds,jitter_seconds:state.settings.default_jitter_seconds,block_retry_delay_seconds:state.settings.default_block_retry_delay_seconds,block_cooldown_seconds:state.settings.default_block_cooldown_seconds,max_block_retries:state.settings.default_max_block_retries,network_route:'direct',avito_impersonation:'chrome',avito_session_mode:'persistent'};const data={...defaults,...search};for(const [k,v] of Object.entries(data)){const el=f.elements.namedItem(k);if(!el||k==='proxy_url'||k==='specific_location')continue;if(el.type==='checkbox')el.checked=!!v;else if(['include_terms','exclude_terms','brands'].includes(k))el.value=(v||[]).join(', ');else el.value=v??''}$('#search-preset').value=search?.preset_id||'';f.elements.preset_id.value=search?.preset_id||'';f.dataset.specificProfile=search?.specific_location?JSON.stringify(search.specific_location):'';if(search?.specific_location)$('#specific-location').value=search.specific_location.display_name;updateLocationEditor();setEditor(state.settings.default_search_editor||'simple');$('#proxy-url').placeholder=search?.proxy_configured?'Proxy saved — leave blank to keep it':'http:// or socks5://';$('#search-dialog').showModal()}
function formPayload(){const f=$('#search-form'),num=n=>f.elements[n].value===''?null:Number(f.elements[n].value),terms=n=>f.elements[n].value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean),specific=f.elements.location_mode.value==='specific'?selectedLocation($('#specific-location').value,f.dataset.specificProfile):null;if(f.elements.location_mode.value==='specific'&&!specific)throw new Error('Choose a known specific city');return{name:f.elements.name.value.trim()||state.searchPresets?.find(x=>x.id===f.elements.preset_id.value)?.name||'Custom search',source:f.elements.source.value,url:f.elements.url.value.trim(),preset_id:f.elements.preset_id.value||null,location_mode:f.elements.location_mode.value,specific_location:specific,enabled:f.elements.enabled.checked,interval_seconds:num('interval_seconds'),jitter_seconds:num('jitter_seconds'),include_terms:terms('include_terms'),exclude_terms:terms('exclude_terms'),brands:terms('brands'),min_price:num('min_price'),max_price:num('max_price'),target_price:num('target_price'),block_retry_delay_seconds:num('block_retry_delay_seconds'),max_block_retries:num('max_block_retries'),block_cooldown_seconds:num('block_cooldown_seconds'),network_route:f.elements.network_route.value,proxy_url:f.elements.proxy_url.value.trim()||null,avito_impersonation:f.elements.avito_impersonation.value.trim(),avito_session_mode:f.elements.avito_session_mode.value}}
function selectedLocation(value,fallback=''){const needle=value.trim().toLocaleLowerCase('ru');const found=state.locations.find(x=>[x.id,x.display_name,...(x.aliases||[])].some(v=>String(v).toLocaleLowerCase('ru')===needle));if(found)return found;if(fallback){const profile=JSON.parse(fallback);if(profile.display_name.toLocaleLowerCase('ru')===needle)return profile}return null}
function updateLocationEditor(){const specific=$('#search-form').elements.location_mode.value==='specific';$('.specific-location').hidden=!specific}

async function loadListings(){if(!state.searches.length)await loadSearches();const q=new URLSearchParams();[['text','#filter-text'],['source','#filter-source'],['status','#filter-status'],['availability','#filter-availability'],['search','#filter-search'],['min_price','#filter-min'],['max_price','#filter-max']].forEach(([k,s])=>{if($(s).value)q.set(k,$(s).value)});if($('#filter-inbox').checked)q.set('inbox_only','true');if($('#filter-new').checked)q.set('new_only','true');if($('#filter-drops').checked)q.set('price_drops','true');if(state.listingSort.field){q.set('sort_by',state.listingSort.field);q.set('sort_direction',state.listingSort.direction)}state.listings=await api('/api/listings?'+q);const body=$('#listing-table');body.innerHTML=state.listings.map(l=>{const prev=l.previous_price,delta=prev!=null&&l.current_price!=null?l.current_price-prev:null,discount=l.market_discount_percent==null?'—':`${l.market_discount_percent>0?'-':'+'}${Math.abs(l.market_discount_percent).toFixed(1)}% market`;return`<tr data-source="${h(l.source)}" data-id="${h(l.external_id)}"><td><input class="select-listing" type="checkbox" aria-label="${h(l.title)}" data-key="${h(l.source)}|${h(l.external_id)}" ${state.selected.has(`${l.source}|${l.external_id}`)?'checked':''}></td><td><span class="source-label">${h(l.source)}</span></td><td><div class="listing-cell">${listingImage(l.primary_image_url)}<div class="listing-cell-copy"><strong>${h(l.title)}</strong><small>${h(l.normalized_model||t('listings.not_normalized'))} · ${h(l.search_names||t('listings.unassigned'))}</small></div></div></td><td class="price">${h(l.price_display)}</td><td class="${delta<0?'drop':delta>0?'rise':''}">${delta==null?'—':`${delta>0?'+':''}${money(delta)}`}</td><td>${h(l.location||'—')}</td><td>${h(ago(l.first_seen))}</td><td>${availabilityBadge(l)}<br><small>${h(freshnessText(l))}</small></td><td>${healthTag(l.status)}</td><td><div class="rating-cell">${scoreBadge(l)}<span class="market-discount">${h(discount)}</span>${conditionBadge(l)}</div></td></tr>`}).join('');bindImageFallbacks(body);$$('.sort-header').forEach(x=>x.querySelector('span').textContent=state.listingSort.field===x.dataset.sort?(state.listingSort.direction==='asc'?'↑':'↓'):'↕');$('#listing-empty').style.display=state.listings.length?'none':'block';body.querySelectorAll('tr').forEach(row=>row.onclick=e=>{if(e.target.matches('input'))return;openListing(row.dataset.source,row.dataset.id)});$$('.select-listing').forEach(x=>x.onchange=()=>{x.checked?state.selected.add(x.dataset.key):state.selected.delete(x.dataset.key);renderBulkActions()});renderBulkActions()}
function renderBulkActions(){const count=state.selected.size,selectedRows=state.listings.filter(row=>state.selected.has(`${row.source}|${row.external_id}`)),dismiss=$('[data-bulk-action="dismiss"]');$('#selected-count').textContent=t('cleanup.selected',{n:count});$('#listing-bulk-actions').classList.toggle('visible',count>0);dismiss.disabled=!selectedRows.some(row=>row.in_working_inbox);dismiss.setAttribute('aria-disabled',String(dismiss.disabled))}
async function openListing(source,id){const l=await api(`/api/listings/${encodeURIComponent(source)}/${encodeURIComponent(id)}`),history=l.price_history||[],discount=l.market_discount_percent==null?'—':`${l.market_discount_percent>0?'-':'+'}${Math.abs(l.market_discount_percent).toFixed(1)}% vs market`;$('#listing-detail').innerHTML=`<div class="modal-head"><div><p class="eyebrow">${h(l.source)} · ${h(l.external_id)}</p><h2 class="detail-title">${h(l.title)}</h2></div><button class="icon-btn" aria-label="${h(t('common.close'))}" onclick="document.querySelector('#listing-dialog').close()">×</button></div>${listingImage(l.primary_image_url,'detail')}<div class="detail-price">${h(l.price_display)}</div><div class="detail-rating">${availabilityBadge(l)} ${scoreBadge(l)} <span class="market-discount">${h(discount)}</span> ${conditionBadge(l)}</div><p class="availability-text">${h(freshnessText(l))}</p><div class="detail-grid"><div class="detail-box"><small>${h(t('listings.source_location'))}</small>${h(l.source)} · ${h(l.location||t('common.unknown'))}</div><div class="detail-box"><small>${h(t('listings.asking_price'))}</small>${money(l.current_price)}</div><div class="detail-box"><small>${h(t('listings.market_median'))}</small>${money(l.market_median)}</div><div class="detail-box"><small>Q1–Q3</small>${money(l.market_q1)} – ${money(l.market_q3)}</div><div class="detail-box"><small>${h(t('listings.estimated_resale'))}</small>${money(l.estimated_resale_price)}</div><div class="detail-box"><small>${h(t('listings.gross_margin'))}</small>${money(l.expected_gross_margin)}</div><div class="detail-box"><small>${h(t('listings.confidence_trend'))}</small>${h(l.confidence)} · ${h(l.market_trend)}</div><div class="detail-box"><small>${h(t('listings.first_last_seen'))}</small>${h(fmtDate(l.first_seen))}<br>${h(fmtDate(l.last_seen))}</div></div><div class="warning-box"><small>${h(t('listings.condition_risk'))}</small>${l.matched_warning_phrases?.length?h(l.matched_warning_phrases.join(', ')):h(t('listings.no_warnings'))}</div><label style="margin-top:16px">${h(t('listings.local_status'))}<select id="detail-status">${['new','reviewed','interesting','ignored','bought'].map(x=>`<option value="${h(x)}" ${x===l.status?'selected':''}>${h(statusLabel(x))}</option>`).join('')}</select></label><div class="price-history"><p class="eyebrow">${h(t('listings.price_history'))}</p>${history.map(x=>`<div class="price-point"><strong>${money(x.price)}</strong><span>${h(fmtDate(x.observed_at))}</span></div>`).join('')||`<p>${h(t('listings.no_history'))}</p>`}</div><div class="modal-actions"><button class="btn ghost" id="open-marketplace">${h(t('listings.open_marketplace'))}</button><button class="btn primary" id="save-status">${h(t('listings.save_status'))}</button></div>`;bindImageFallbacks($('#listing-detail'));$('#listing-dialog').showModal();$('#open-marketplace').onclick=()=>openExternal(l.url).catch(error=>toast(error.message,true));$('#save-status').onclick=async()=>{await api(`/api/listings/${encodeURIComponent(source)}/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status:$('#detail-status').value})});toast(t('listings.status_saved'));$('#listing-dialog').close();if(state.page==='listings')loadListings()}}

function listingCandidate(l,label,kind='candidate-card'){const discount=l?.market_discount_percent;return l?`<button class="${kind}" data-source="${h(l.source)}" data-id="${h(l.external_id)}"><small>${h(label)}</small><strong>${h(l.title)}</strong><span>${money(l.current_price)} · ${discount==null?'market comparison unavailable':h(`${discount>0?'-':'+'}${Math.abs(discount).toFixed(1)}% vs market`)}</span><div>${availabilityBadge(l)} ${scoreBadge(l)} ${conditionBadge(l)}</div></button>`:`<div class="candidate-card unavailable"><small>${h(label)}</small><strong>INSUFFICIENT DATA</strong></div>`}
function bindListingCandidates(root){root.querySelectorAll('[data-source][data-id]').forEach(x=>x.onclick=()=>openListing(x.dataset.source,x.dataset.id))}
async function loadMarket(){const category=$('#market-category').value,params=new URLSearchParams({q:$('#market-query').value});if(category)params.set('category',category);const products=await api('/api/market?'+params);if(!products.some(p=>p.comparable_key===state.marketKey))state.marketKey=products[0]?.comparable_key||null;$('#market-results').innerHTML=products.length?products.map(p=>`<button class="market-product ${p.comparable_key===state.marketKey?'active':''}" role="option" aria-selected="${p.comparable_key===state.marketKey}" data-key="${h(p.comparable_key)}"><strong>${h(p.display_label)}</strong><small>${p.listing_count} listings · updated ${h(ago(p.last_updated))}</small></button>`).join(''):'<div class="empty" style="display:block">No market data collected yet.</div>';$$('.market-product').forEach(x=>x.onclick=()=>selectMarket(x.dataset.key));const opportunities=await api('/api/market/opportunities'),opportunityRoot=$('#top-opportunities');opportunityRoot.innerHTML=opportunities.length?opportunities.slice(0,6).map(l=>listingCandidate(l,'TOP OPPORTUNITY','opportunity')).join(''):'<div class="empty" style="display:block">No active listings currently observed.</div>';bindListingCandidates(opportunityRoot);if(state.marketKey)await selectMarket(state.marketKey,false);else{$('#market-empty').hidden=false;$('#market-content').hidden=true}}
async function selectMarket(key,reloadList=true){state.marketKey=key;$$('.market-product').forEach(x=>{const selected=x.dataset.key===key;x.classList.toggle('active',selected);x.setAttribute('aria-selected',selected);if(selected)x.scrollIntoView({block:'nearest'})});const data=await api(`/api/market/${encodeURIComponent(key)}?range=${state.marketRange}`),s=data.summary,r=data.retail_summary;$('#market-empty').hidden=true;$('#market-content').hidden=false;$('#market-chart-title').textContent=`${s.normalized_model||key} market movement`;const gap=r?.representative_price?((s.median-r.representative_price)/r.representative_price*100).toFixed(1):null;const metrics=[['USED MEDIAN',money(s.median)],['NEW RETAIL',money(r?.representative_price)],['USED / NEW GAP',gap==null?'—':`${gap}%`],['TYPICAL RANGE',`${money(s.q1)} – ${money(s.q3)}`],['7D / 30D TREND',`${s.trend_7d_percent??'—'}% · ${s.trend_30d_percent??'—'}%`],['OBSERVATIONS / ACTIVE',`${s.historical_observation_count} · ${s.active_listing_count}`]];$('#market-summary').innerHTML=metrics.map(m=>`<article class="market-metric"><small>${m[0]}</small><strong>${h(m[1])}</strong></article>`).join('');const candidates=$('#market-candidates');candidates.innerHTML=s.active_listing_count?listingCandidate(s.cheapest_listing,'CHEAPEST OBSERVED')+listingCandidate(s.strongest_candidate,'STRONGEST CANDIDATE'):'<div class="candidate-card unavailable"><strong>No active listings currently observed</strong></div>';bindListingCandidates(candidates);drawMarketChart(data.snapshots);renderRetail(r,data.retail_history);await loadRetailBrowserWorkspace(key)}

async function loadRetailBrowserWorkspace(key=state.marketKey){if(!key)return;const [browser,mappings]=await Promise.all([api('/api/retail/browser'),api('/api/retail/mappings?comparable_key='+encodeURIComponent(key))]);const badge=$('#retail-browser-status'),engine=browser.engine[0].toUpperCase()+browser.engine.slice(1);badge.textContent=browser.state[0].toUpperCase()+browser.state.slice(1)+' · '+engine;badge.className='tag '+(browser.state==='open'?'healthy':browser.state==='error'?'failed':'experimental');$('#retail-browser-engine').value=browser.engine;$('#retail-browser-engine').disabled=browser.state==='open'||browser.state==='starting';$('#retail-mappings').innerHTML=mappings.map(m=>{const last=m.last_observation,meta=m.validation==='valid'?`ID ${h(m.product_id||'—')}${last?` · last ${money(last.price)} · ${h(ago(last.observed_at))}`:' · no browser capture yet'}`:h(m.validation);return`<div class="retail-mapping-row" data-retailer="${h(m.retailer)}"><strong>${h(m.retailer)}</strong><input class="mapping-url" value="${h(m.product_url||'')}" placeholder="Canonical product URL"><div class="retail-mapping-actions"><button class="btn ghost mapping-save">Save</button><button class="btn ghost mapping-open" ${m.validation!=='valid'?'disabled':''}>Open</button><button class="btn secondary mapping-capture" ${m.validation!=='valid'?'disabled':''}>Capture</button><button class="btn danger mapping-delete" ${m.product_url?'':'disabled'}>Delete</button></div><div class="retail-mapping-meta">${meta}</div></div>`}).join('');bindRetailMappings()}
function bindRetailMappings(){$$('#retail-mappings .retail-mapping-row').forEach(row=>{const retailer=row.dataset.retailer,input=row.querySelector('.mapping-url'),payload=()=>({comparable_key:state.marketKey,retailer});row.querySelector('.mapping-save').onclick=async()=>{try{await api('/api/retail/mapping',{method:'POST',body:JSON.stringify({...payload(),product_url:input.value.trim()})});toast(`${retailer.toUpperCase()} mapping saved`);loadRetailBrowserWorkspace()}catch(e){toast(e.message,true)}};row.querySelector('.mapping-delete').onclick=async()=>{if(!confirm(`Delete ${retailer.toUpperCase()} mapping?`))return;await api('/api/retail/mapping/delete',{method:'POST',body:JSON.stringify(payload())});toast('Mapping deleted');loadRetailBrowserWorkspace()};row.querySelector('.mapping-open').onclick=async()=>{try{await api('/api/retail/browser/navigate',{method:'POST',body:JSON.stringify(payload())});toast(`${retailer.toUpperCase()} product opened`);loadRetailBrowserWorkspace()}catch(e){toast(e.message,true)}};row.querySelector('.mapping-capture').onclick=async()=>{const root=$('#retail-capture-result');try{const result=await api('/api/retail/browser/capture',{method:'POST',body:JSON.stringify({...payload(),confirmed_region:$('#retail-browser-region').value.trim()})});const observation=result.observations[0];root.className='browser-capture-result visible '+(observation?'success':'error');root.innerHTML=observation?`Captured <strong>${h(retailer.toUpperCase())}</strong> · ${h(observation.product_title)} · ${money(observation.price)} · ${h(observation.availability)} · ${h(observation.region)} · ${h(observation.match_confidence)}`:h(result.error||'No reliable product match');await selectMarket(state.marketKey,false)}catch(e){root.className='browser-capture-result visible error';root.textContent=e.message}}})}
function renderRetail(summary,points){if(!summary){$('#retail-summary').innerHTML='';$('#retail-toggles').innerHTML='';$('#retail-chart').innerHTML='<div class="empty" style="display:block">Retail data not configured yet.</div>';return}$('#retail-summary').innerHTML=`<div class="retail-breakdown"><strong>${money(summary.representative_price)} representative · ${money(summary.cheapest_price)} cheapest</strong><span>${summary.retailer_count} retailers · ${summary.offer_count} offers · ${h(summary.confidence)} · updated ${h(ago(summary.last_updated))}</span>${summary.retailers.map(x=>`<span>${h(x.retailer.toUpperCase())}: ${money(x.representative_price)} ${x.stale?'· stale':''}</span>`).join('')}</div>`;const names=[...new Set(points.map(x=>x.retailer))];$('#retail-toggles').innerHTML=names.map(n=>`<button class="${state.retailLines.has(n)?'active':''}" data-retailer="${h(n)}">${h(n.toUpperCase())}</button>`).join('');$$('#retail-toggles button').forEach(b=>b.onclick=()=>{state.retailLines.has(b.dataset.retailer)?state.retailLines.delete(b.dataset.retailer):state.retailLines.add(b.dataset.retailer);renderRetail(summary,points)});drawRetailChart(points.filter(x=>state.retailLines.has(x.retailer)))}
function drawRetailChart(points){const root=$('#retail-chart');if(!points.length){root.innerHTML='<div class="empty" style="display:block">No retail points in this range.</div>';return}const w=900,hg=260,p=42,prices=points.flatMap(x=>[x.representative_price,x.cheapest_price]),min=Math.min(...prices)*.95,max=Math.max(...prices)*1.05,span=max-min||1,times=[...new Set(points.map(x=>x.observed_at))].sort(),x=t=>p+(w-p*2)*(times.length===1?.5:times.indexOf(t)/(times.length-1)),y=v=>hg-p-(v-min)/span*(hg-p*2),style=getComputedStyle(document.documentElement),colors={dns:style.getPropertyValue('--chart-a'),ozon:style.getPropertyValue('--chart-b'),wildberries:style.getPropertyValue('--chart-c')};root.innerHTML=`<svg viewBox="0 0 ${w} ${hg}" role="img" aria-label="Retail price history"><line class="chart-axis" x1="${p}" y1="${hg-p}" x2="${w-p}" y2="${hg-p}"/>${[...new Set(points.map(q=>q.retailer))].map(n=>{const rows=points.filter(q=>q.retailer===n);return`<polyline fill="none" stroke="${colors[n]||style.getPropertyValue('--accent')}" stroke-width="2" points="${rows.map(q=>`${x(q.observed_at)},${y(q.representative_price)}`).join(' ')}"/>${rows.map(q=>`<circle cx="${x(q.observed_at)}" cy="${y(q.representative_price)}" r="4" fill="${colors[n]||style.getPropertyValue('--accent')}"><title>${h(fmtDate(q.observed_at))} · ${h(n)} · ${money(q.representative_price)} · cheapest ${money(q.cheapest_price)} · ${q.offer_count} offers · ${h(q.availability)}</title></circle>`).join('')}`}).join('')}</svg>`}
function drawMarketChart(points){const root=$('#used-chart');if(!points.length){root.innerHTML='<div class="empty" style="display:block">No snapshots in this time range.</div>';return}const w=900,hg=300,p=42,values=points.flatMap(x=>[x.q1,x.q3]),min=Math.min(...values)*.95,max=Math.max(...values)*1.05,span=max-min||1,x=i=>p+(w-p*2)*(points.length===1?.5:i/(points.length-1)),y=v=>hg-p-(v-min)/(span)*(hg-p*2),upper=points.map((d,i)=>`${x(i)},${y(d.q3)}`).join(' '),lower=[...points].reverse().map((d,i)=>`${x(points.length-1-i)},${y(d.q1)}`).join(' '),line=points.map((d,i)=>`${x(i)},${y(d.median)}`).join(' ');root.innerHTML=`<svg viewBox="0 0 ${w} ${hg}" role="img" aria-label="Used market price history"><line class="chart-axis" x1="${p}" y1="${hg-p}" x2="${w-p}" y2="${hg-p}"/><polygon class="chart-band" points="${upper} ${lower}"/><polyline class="chart-line" points="${line}"/>${points.map((d,i)=>`<circle class="chart-point" cx="${x(i)}" cy="${y(d.median)}" r="5" data-i="${i}"/>`).join('')}</svg>`;root.querySelectorAll('.chart-point').forEach(el=>{el.onmouseenter=e=>{const d=points[Number(el.dataset.i)],tip=$('#chart-tooltip');tip.innerHTML=`<strong>${h(fmtDate(d.snapshot_at))}</strong><br>Median ${money(d.median)}<br>Q1–Q3 ${money(d.q1)} – ${money(d.q3)}<br>${d.sample_count} observed · ${d.new_listings_count} new · ${d.price_drop_count} drops<br>${d.disappeared_count} disappeared / turnover signal`;tip.style.display='block';tip.style.left=`${e.clientX-320}px`;tip.style.top=`${e.clientY-180}px`};el.onmouseleave=()=>$('#chart-tooltip').style.display='none'})}

async function loadHistory(){const events=await api('/api/history');$('#history-drops').textContent=events.filter(x=>x.event_type==='price_drop').length;$('#history-new').textContent=events.filter(x=>x.event_type==='new').length;renderActivity('#history-list',events,false)}
function renderActivity(target,events,compact){$(target).innerHTML=events.length?events.map(e=>{const drop=e.event_type==='price_drop',icon=drop?'↓':e.event_type==='new'?'＋':'↕';const detail=drop?`${money(e.old_price)} → ${money(e.new_price)}`:e.event_type==='new'?`${e.price_display||money(e.new_price)} · ${e.search_name||''}`:`${money(e.old_price)} → ${money(e.new_price)}`;return`<div class="activity-item"><span class="activity-icon">${icon}</span><div><strong>${h(e.title||e.event_type)}</strong><p>${h(detail)} · ${h(e.source)}</p></div><time>${h(ago(e.occurred_at))}</time></div>`}).join(''):'<div class="empty" style="display:block">No monitoring events yet.</div>'}
async function loadSources(){const sources=await api('/api/sources');$('#source-details').innerHTML=sources.map(s=>`<article class="source-detail"><div class="hero"><div><p class="eyebrow">${h(t('sources.marketplace'))}</p><h2>${h(s.source)}</h2></div>${healthTag(s.health)}</div><div class="detail-list"><div class="detail-row"><span>${h(t('sources.last_success'))}</span><strong>${h(fmtDate(s.last_success_at))}</strong></div><div class="detail-row"><span>${h(t('sources.http_transport'))}</span><strong>${h(s.last_http_status??'—')} · ${h(s.transport??'—')}</strong></div><div class="detail-row"><span>${h(t('sources.raw_valid'))}</span><strong>${h(s.raw_items??0)} / ${h(s.valid_listings??0)}</strong></div><div class="detail-row"><span>${h(t('sources.rejected_priced'))}</span><strong>${h(s.rejected_items??0)} / ${h(s.priced_listings??0)}</strong></div><div class="detail-row"><span>${h(t('sources.rejection_rate'))}</span><strong>${h(s.rejection_rate??0)}%</strong></div><div class="detail-row"><span>${h(t('sources.blocked_until'))}</span><strong>${h(s.blocked_until?fmtDate(s.blocked_until):'—')}</strong></div></div><div class="profile-box"><small>${h(t('sources.network_profile'))}</small>${s.network_profile?`${h(s.network_profile.route)} · ${h(s.network_profile.proxy_scheme||'no proxy')} ${s.network_profile.impersonation?'· '+h(s.network_profile.impersonation):''} ${s.network_profile.session_mode?'· '+h(s.network_profile.session_mode):''}`:h(t('sources.not_configured'))}</div>${s.source==='youla'?`<p>${h(t('sources.youla_note'))}</p>`:''}</article>`).join('')}

async function loadSettings(){const [settings,locations,project,integration]=await Promise.all([api('/api/settings'),api('/api/locations'),api('/api/project'),api('/api/desktop-integration')]);state.settings=settings;state.locations=locations;state.project=project;state.desktopIntegration=integration;I18n.setLanguage(settings.interface_language);applyAppearance(settings);refreshPageTitle();renderProjectInfo();$$('[data-setting]').forEach(x=>x.value=state.settings[x.dataset.setting]);const loc=state.settings.default_location.trim().startsWith('{')?JSON.parse(state.settings.default_location):state.locations.find(x=>x.id===state.settings.default_location);if(loc&&!state.locations.some(x=>x.id===loc.id))state.locations.push(loc);$('#location-options').innerHTML=state.locations.map(x=>`<option value="${h(x.display_name)}">${h(x.aliases?.join(', ')||x.id)}</option>`).join('');$('#default-location-input').value=loc?.display_name||'';$('#default-location-option').textContent=`${t('search.default')} — ${loc?.display_name||t('status.not-configured')}`;renderLocationStatus(loc);const sources=await api('/api/sources');$('#settings-source-health').innerHTML=sources.map(x=>`<div class="setting-row"><div><strong>${h(x.source.toUpperCase())}</strong><p>${x.searches} ${h(t('sources.configured_searches'))}</p></div>${healthTag(x.health)}</div>`).join('');$('#storage-info').innerHTML=`<p>${h(t('settings.database'))}</p><p>${h(t('settings.exports'))}</p>`}
function renderProjectInfo(){if(!state.project)return;$('#about-version').textContent=state.project.version;$$('[data-i18n="release.alpha"]').forEach(element=>element.textContent=t(`release.${state.project.release_channel}`));renderUpdateStatus();renderDesktopIntegration()}
function setSettingsSection(button){$$('.settings-nav button').forEach(x=>x.classList.toggle('active',x===button));let active=null;$$('.settings-section').forEach(x=>{const selected=x.dataset.section===button.dataset.settingsSection;x.classList.toggle('active',selected);if(selected)active=x});$('#settings-actions').hidden=active?.dataset.editable!=='true'}
function renderUpdateStatus(){const box=$('#update-status'),button=$('#check-updates'),release=$('#view-release'),result=state.updateResult;button.disabled=state.updateChecking;button.textContent=t(state.updateChecking?'updates.checking':'updates.check');release.hidden=true;if(state.updateChecking){box.innerHTML=`<strong>${h(t('updates.checking'))}</strong><p class="muted">${h(t('updates.checking_help'))}</p>`;return}if(!result){box.innerHTML=`<strong>${h(t('updates.manual_title'))}</strong><p class="muted">${h(t('updates.manual_help'))}</p>`;return}if(result.status==='up_to_date'){box.innerHTML=`<strong>${h(t('updates.up_to_date'))}</strong><p class="muted">${h(t('updates.latest',{version:result.current_version}))}</p>`;return}if(result.status==='update_available'){box.innerHTML=`<strong>${h(t('updates.available',{version:result.latest_version}))}</strong><p class="muted">${h(result.release_name||t('updates.manual_install'))}</p>`;release.hidden=false;return}if(result.status==='no_release'){box.innerHTML=`<strong>${h(t('updates.no_release'))}</strong><p class="muted">${h(t('updates.no_release_help'))}</p>`;return}box.innerHTML=`<strong>${h(t('updates.error'))}</strong><p class="muted">${h(t('updates.error_help'))}</p>`;button.textContent=t('updates.try_again')}
function renderDesktopIntegration(){const integration=state.desktopIntegration||{status:'unavailable',can_install:false},result=state.integrationResult,prompt=$('#integration-prompt'),section=$('#about-installation'),status=$('#integration-status'),aboutButton=$('#about-integration-install'),promptButton=$('#integration-prompt-install');const available=integration.can_install&&integration.status!=='unavailable',dismissed=Boolean(Number(state.settings.linux_integration_prompt_dismissed));section.hidden=!available;prompt.hidden=!available||integration.status!=='portable'||dismissed||result?.result==='installed';for(const button of [aboutButton,promptButton])button.disabled=state.integrationInstalling;if(!available)return;if(state.integrationInstalling){status.innerHTML=`<strong>${h(t('integration.installing'))}</strong><p>${h(t('integration.installing_help'))}</p>`;aboutButton.textContent=t('integration.installing');return}if(result?.result==='error'){status.innerHTML=`<strong>${h(t('integration.error'))}</strong><p>${h(t('integration.error_help'))}</p>`;aboutButton.textContent=t('integration.try_again');return}if(integration.status==='integrated'){status.innerHTML=`<strong>${h(result?.result==='installed'?t('integration.added'):t('integration.installed'))}</strong><p>${h(t('integration.installed_help'))}</p>`;aboutButton.textContent=t('integration.reinstall');return}status.innerHTML=`<strong>${h(t('integration.portable'))}</strong><p>${h(t('integration.portable_help'))}</p>`;aboutButton.textContent=t('integration.add')}
async function installDesktopIntegration(){if(state.integrationInstalling)return;state.integrationInstalling=true;state.integrationResult=null;renderDesktopIntegration();try{const result=await api('/api/desktop-integration/install',{method:'POST'});state.integrationResult=result;state.desktopIntegration={status:result.status,can_install:result.can_install};if(result.result==='installed')state.settings.linux_integration_prompt_dismissed=1}catch{state.integrationResult={result:'error'}}finally{state.integrationInstalling=false;renderDesktopIntegration()}}
async function dismissIntegrationPrompt(){state.settings=await api('/api/settings',{method:'POST',body:JSON.stringify({linux_integration_prompt_dismissed:1})});renderDesktopIntegration()}
async function checkForUpdates(){if(state.updateChecking)return;state.updateChecking=true;renderUpdateStatus();try{state.updateResult=await api('/api/updates/check',{method:'POST'})}catch{state.updateResult={status:'api_error'}}finally{state.updateChecking=false;renderUpdateStatus()}}
function openProjectLink(key){const url=state.project?.urls?.[key];if(!url)return Promise.reject(new Error(t('updates.link_error')));return openExternal(url)}
function renderLocationStatus(loc){if(!loc){$('#location-status').innerHTML='<p class="muted">Choose a known city from the list.</p>';return}const status=loc.source_status||{avito:loc.source_tokens?.avito?'ready':'not-configured',farpost:loc.source_tokens?.farpost?'ready':'not-configured',youla:'unsupported'},label=v=>v==='ready'?'Ready':v==='unsupported'?'Unsupported':'Not configured';$('#location-status').innerHTML=`<div class="setting-row"><div><strong>${h(loc.display_name)}</strong><p>${['avito','farpost','youla'].map(s=>`${h(s[0].toUpperCase()+s.slice(1))}: ${h(label(status[s]))}`).join(' · ')}</p></div>${healthTag(status.avito==='ready'?'healthy':'experimental')}</div>`}
async function saveSettings(){const payload={};$$('[data-setting]').forEach(x=>payload[x.dataset.setting]=['default_export_format','default_search_editor','interface_language','appearance_mode','color_theme','retail_region'].includes(x.dataset.setting)?x.value:Number(x.value));const loc=selectedLocation($('#default-location-input').value);if(!loc)throw new Error(t('settings.choose_location'));payload.default_location=loc.builtin?loc.id:JSON.stringify({id:loc.id,display_name:loc.display_name,country:loc.country,source_tokens:loc.source_tokens,aliases:loc.aliases||[]});state.settings=await api('/api/settings',{method:'POST',body:JSON.stringify(payload)});I18n.setLanguage(state.settings.interface_language);applyAppearance(state.settings);refreshPageTitle();toast(t('settings.saved'));await loadSettings();await loadPage(state.page)}
async function learnCustomLocation(){const name=$('#custom-location-name').value.trim(),source=$('#custom-location-source').value,url=$('#custom-location-url').value.trim();if(!name||!url)throw new Error('Display name and known-working URL are required');const id='custom-'+name.toLocaleLowerCase('ru').replace(/[^a-zа-яё0-9]+/gi,'-').replace(/^-|-$/g,'');const profile=await api('/api/location/learn',{method:'POST',body:JSON.stringify({display_name:name,location_id:id,source,url,make_default:$('#custom-location-default').checked})});state.locations.push(profile);$('#default-location-input').value=profile.display_name;renderLocationStatus(profile);toast('Location mapping saved locally');if($('#custom-location-default').checked)loadSettings()}
async function openCleanup(){const preview=await api('/api/cleanup/preview');$('#cleanup-summary').innerHTML=`<div class="cleanup-count"><span>${h(t('cleanup.aged'))}</span><strong>${preview.aged_out_count}</strong></div><div class="cleanup-count"><span>${h(t('cleanup.to_archive'))}</span><strong>${preview.archive_count}</strong></div><div class="cleanup-count"><span>${h(t('cleanup.retention_eligible'))}</span><strong>${preview.retention_eligible_count}</strong></div>`;$('#cleanup-inbox').disabled=!preview.aged_out_count;$('#cleanup-archive').disabled=!preview.archive_count;$('#cleanup-dialog').showModal()}
async function applyCleanup(removeFromInbox,archiveDisappeared){const result=await api('/api/cleanup/apply',{method:'POST',body:JSON.stringify({remove_from_inbox:removeFromInbox,archive_disappeared:archiveDisappeared})});toast(`${result.aged_out_count+result.archive_count} ${t('cleanup.title').toLocaleLowerCase()}`);await openCleanup();await loadListings();await loadOverview()}
async function applyBulkAction(action){let selected=[...state.selected].map(key=>key.split('|'));if(action==='dismiss')selected=selected.filter(([source,id])=>state.listings.some(row=>row.source===source&&row.external_id===id&&row.in_working_inbox));if(!selected.length)return;const result=await api('/api/listings/bulk',{method:'POST',body:JSON.stringify({selected,action})});state.selected.clear();toast(`${result.changed} · ${t('cleanup.title')}`);await loadListings()}

async function pollRuntime(){try{const r=await api('/api/runtime');$('#runtime-state').textContent=r.state;$('#side-runtime').textContent=r.state;$('.runtime-dot').style.background=r.state==='Idle'?'var(--text-tertiary)':'var(--accent)'}catch{}setTimeout(pollRuntime,(state.settings.ui_refresh_seconds||2)*1000)}

$$('.nav-item').forEach(x=>x.onclick=()=>go(x.dataset.page));$$('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));$('#new-search-btn').onclick=()=>openSearch();$('#search-form').onsubmit=async e=>{e.preventDefault();try{const original=$('#search-original-name').value,payload=formPayload();const path=original?`/api/searches/${encodeURIComponent(original)}`:'/api/searches';await api(path,{method:original?'PUT':'POST',body:JSON.stringify(payload)});$('#search-dialog').close();toast(original?'Search updated':'Search created');loadSearches()}catch(err){toast(err.message,true)}};$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-delete').onclick=async()=>{try{await api(`/api/searches/${encodeURIComponent(state.deleteName)}`,{method:'DELETE'});$('#confirm-dialog').close();toast('Search deleted');loadSearches()}catch(e){toast(e.message,true)}};$('#scan-btn').onclick=async()=>{const r=await api('/api/scan',{method:'POST'});toast(r.started?'Scan started':'A scan is already running')};$('#start-btn').onclick=async()=>{const r=await api('/api/monitor/start',{method:'POST'});toast(r.started?'Monitoring started':'Monitoring is already active')};$('#stop-btn').onclick=async()=>{const r=await api('/api/monitor/stop',{method:'POST'});toast(r.stopped?'Monitoring stopped':'Monitoring was already idle')};$('#apply-filters').onclick=loadListings;$('#clear-filters').onclick=()=>{$$('#page-listings input').forEach(x=>x.type==='checkbox'?x.checked=false:x.value='');$$('#page-listings select').forEach(x=>x.value='');loadListings()};$('#export-btn').onclick=()=>$('#export-menu').classList.toggle('open');$$('#export-menu button').forEach(x=>x.onclick=async()=>{const r=await api('/api/export',{method:'POST',body:JSON.stringify({format:x.dataset.format})});$('#export-menu').classList.remove('open');toast(`Exported to ${r.path}`)});$('#copy-btn').onclick=async()=>{const selected=[...state.selected].map(x=>x.split('|'));const r=await api('/api/copy',{method:'POST',body:JSON.stringify({selected,include_new:!selected.length,include_interesting:!selected.length})});await navigator.clipboard.writeText(r.text);toast(`Copied ${r.text.split('\n').length-1} listings`)};

$$('.sort-header').forEach(x=>x.onclick=()=>{const same=state.listingSort.field===x.dataset.sort;if(!same)state.listingSort={field:x.dataset.sort,direction:'desc'};else if(state.listingSort.direction==='desc')state.listingSort.direction='asc';else state.listingSort={field:null,direction:null};loadListings()});
api('/api/search-presets').then(presets=>{state.searchPresets=presets;$('#search-preset').insertAdjacentHTML('beforeend',presets.map(p=>`<option value="${h(p.id)}">${h(p.label)} · ${h(p.source)}</option>`).join(''));$('#search-preset').onchange=e=>{const f=$('#search-form'),p=presets.find(x=>x.id===e.target.value);f.elements.preset_id.value=p?.id||'';if(!p)return;for(const [k,v] of Object.entries(p)){const el=f.elements.namedItem(k);if(!el)continue;if(el.type==='checkbox')el.checked=!!v;else if(['include_terms','exclude_terms','brands'].includes(k))el.value=(v||[]).join(', ');else el.value=v??''}f.elements.url.value='';updateSourceControls()}});
loadSearches().then(()=>loadOverview());pollRuntime();
document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('.close-search').forEach(x=>x.onclick=()=>document.querySelector('#search-dialog').close()));
document.addEventListener('DOMContentLoaded',()=>{$('#interface-language').onchange=e=>{I18n.setLanguage(e.target.value);refreshPageTitle();renderProjectInfo()}});
document.addEventListener('DOMContentLoaded',()=>{$$('[data-appearance-mode]').forEach(button=>button.onclick=()=>{$('#appearance-mode').value=button.dataset.appearanceMode;state.settings.appearance_mode=button.dataset.appearanceMode;applyAppearance()});$$('[data-color-theme]').forEach(button=>button.onclick=()=>{$('#color-theme').value=button.dataset.colorTheme;state.settings.color_theme=button.dataset.colorTheme;applyAppearance()});applyAppearance()});
document.addEventListener('DOMContentLoaded',()=>{$('#save-settings').onclick=async()=>{try{await saveSettings()}catch(e){toast(e.message,true)}};loadSettings();$$('.settings-nav button').forEach(b=>b.onclick=()=>setSettingsSection(b));setSettingsSection($('.settings-nav button.active'));$$('.editor-tabs button').forEach(b=>b.onclick=()=>setEditor(b.dataset.editor));$('#search-form').elements.location_mode.onchange=updateLocationEditor;$('#search-form').elements.source.onchange=updateSourceControls;$('#default-location-input').oninput=e=>renderLocationStatus(selectedLocation(e.target.value));$('#learn-location').onclick=async()=>{try{await learnCustomLocation()}catch(e){toast(e.message,true)}};$('#copy-diagnostics').onclick=async()=>{const r=await api('/api/diagnostics');await navigator.clipboard.writeText(r.text);toast(t('support.diagnostics_copied'))};$$('[data-project-link]').forEach(button=>button.onclick=()=>openProjectLink(button.dataset.projectLink).catch(error=>toast(error.message,true)));$('#check-updates').onclick=()=>checkForUpdates();$('#view-release').onclick=()=>{const url=state.updateResult?.release_url;if(url)openExternal(url).catch(error=>toast(error.message,true))};$('#integration-prompt-install').onclick=$('#about-integration-install').onclick=()=>installDesktopIntegration();$('#integration-prompt-dismiss').onclick=()=>dismissIntegrationPrompt().catch(error=>toast(error.message,true))});
document.addEventListener('DOMContentLoaded',()=>{$('#open-cleanup').onclick=()=>openCleanup().catch(e=>toast(e.message,true));$('#close-cleanup').onclick=$('#cleanup-cancel').onclick=()=>$('#cleanup-dialog').close();$('#cleanup-inbox').onclick=()=>applyCleanup(true,false).catch(e=>toast(e.message,true));$('#cleanup-archive').onclick=()=>applyCleanup(false,true).catch(e=>toast(e.message,true));$$('[data-bulk-action]').forEach(button=>button.onclick=()=>applyBulkAction(button.dataset.bulkAction).catch(e=>toast(e.message,true)))});
document.addEventListener('DOMContentLoaded',()=>{
  $('#market-category').insertAdjacentHTML('beforeend','<option value="motherboard">Motherboards</option>');
  $('#market-search-btn').onclick=loadMarket;
  $('#market-query').onkeydown=e=>{if(e.key==='Enter')loadMarket()};
  $('#market-category').onchange=loadMarket;
  $('#refresh-retail').onclick=async()=>{if(!state.marketKey)return;const active=$('.market-product.active strong');const result=await api('/api/retail/refresh',{method:'POST',body:JSON.stringify({comparable_key:state.marketKey,query:active?.textContent||state.marketKey})});toast(result.started?'Retail refresh started':'Retail refresh already running')};
  $$('#market-ranges button').forEach(x=>x.onclick=()=>{state.marketRange=x.dataset.range;$$('#market-ranges button').forEach(b=>b.classList.toggle('active',b===x));if(state.marketKey)selectMarket(state.marketKey,false)});
});
document.addEventListener('DOMContentLoaded',()=>{$('#retail-browser-engine').onchange=async e=>{try{await api('/api/retail/browser/engine',{method:'POST',body:JSON.stringify({engine:e.target.value})});toast('Retail browser engine changed');loadRetailBrowserWorkspace()}catch(error){toast(error.message,true);loadRetailBrowserWorkspace()}};$('#open-retail-browser').onclick=async()=>{try{await api('/api/retail/browser/open',{method:'POST'});toast('Retail browser opened');loadRetailBrowserWorkspace()}catch(e){toast(e.message,true)}};$('#close-retail-browser').onclick=async()=>{await api('/api/retail/browser/close',{method:'POST'});toast('Retail browser closed');loadRetailBrowserWorkspace()};$('#reset-retail-browser').onclick=async()=>{if(!confirm('Close the retail browser and permanently reset only its dedicated profile?'))return;await api('/api/retail/browser/reset',{method:'POST',body:JSON.stringify({confirmed:true})});toast('Retail browser profile reset');loadRetailBrowserWorkspace()}});
